def categories_from_text(apps, schema_editor):
    ItemCategory = apps.get_model("core", "ItemCategory")
    ShopItem = apps.get_model("core", "ShopItem")
    for i, name in enumerate(DEFAULT_CATEGORIES):
        ItemCategory.objects.get_or_create(name=name, defaults={"sort": (i + 1) * 10})
    for item in ShopItem.objects.order_by("pk"):
        cat, _ = ItemCategory.objects.get_or_create(name=OLD_LABELS.get(item.category, "Other items"))
        item.category_ref = cat
        item.save(update_fields=["category_ref"])


